CREATE DATABASE IF NOT EXISTS consultancy_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE consultancy_db;

CREATE TABLE IF NOT EXISTS site_settings (setting_key VARCHAR(80) PRIMARY KEY, setting_value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS admins (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS services (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(120) UNIQUE NOT NULL, icon VARCHAR(40) NOT NULL, title VARCHAR(180) NOT NULL, short_text TEXT NOT NULL, description TEXT NOT NULL, features JSON NULL, sort_order INT NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS workflow_steps (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, step VARCHAR(10) NOT NULL, title VARCHAR(180) NOT NULL, description TEXT NOT NULL, sort_order INT NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS projects (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category VARCHAR(60) NOT NULL, year SMALLINT NOT NULL, title VARCHAR(200) NOT NULL, location VARCHAR(200) NOT NULL, summary TEXT NOT NULL, detail TEXT NOT NULL, scope JSON NULL, stats JSON NULL, image VARCHAR(255) DEFAULT NULL, sort_order INT NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS gallery (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category VARCHAR(60) NOT NULL, title VARCHAR(200) NOT NULL, image VARCHAR(255) NOT NULL, sort_order INT NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS team_members (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, role VARCHAR(180) NOT NULL, bio TEXT NOT NULL, image VARCHAR(255) DEFAULT NULL, sort_order INT NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS milestones (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, year VARCHAR(20) NOT NULL, text TEXT NOT NULL, sort_order INT NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS company_values (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(160) NOT NULL, text TEXT NOT NULL, sort_order INT NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS testimonials (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, project VARCHAR(200) NOT NULL, quote TEXT NOT NULL, sort_order INT NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS office_hours (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, day_name VARCHAR(20) UNIQUE NOT NULL, hours VARCHAR(80) NOT NULL, day_order INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS site_stats (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, value VARCHAR(50) NOT NULL, label VARCHAR(120) NOT NULL, sort_order INT NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS enquiries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, email VARCHAR(190) NOT NULL, phone VARCHAR(40) DEFAULT NULL, service VARCHAR(180) NOT NULL, message TEXT NOT NULL, status ENUM('new','read','replied','closed') NOT NULL DEFAULT 'new', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(status), INDEX(created_at));
